source.declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : VARIANT;
    buffer : VARIANT;
END_VAR
VAR
    enqueuePrev : BOOL;
    dequeuePrev : BOOL;
    head : DINT;
    tail : DINT;
    capacity : DINT;
    itemInfo : VAR_INFO;
    bufferInfo : VAR_INFO;
    elementSize : UDINT;
    pItem : POINTER TO BYTE;
    pBuffer : POINTER TO BYTE;
    pSrc : POINTER TO BYTE;
    pDst : POINTER TO BYTE;
    enqEdge : BOOL;
    deqEdge : BOOL;
    i : UDINT;
END_VAR

source.implementation:
status := 0;

IF reset THEN
    elementCount := 0;
    head := 0;
    tail := 0;
    enqueuePrev := enqueue;
    dequeuePrev := dequeue;
ELSE
    enqEdge := enqueue AND NOT enqueuePrev;
    deqEdge := dequeue AND NOT dequeuePrev;
    enqueuePrev := enqueue;
    dequeuePrev := dequeue;

    itemInfo := __VARINFO(item);
    bufferInfo := __VARINFO(buffer);
    elementSize := itemInfo.Size;
    IF elementSize > 0 THEN
        capacity := DINT(bufferInfo.Size / elementSize);
    ELSE
        capacity := 0;
    END_IF;
    pItem := itemInfo.pData;
    pBuffer := bufferInfo.pData;

    IF enqEdge THEN
        IF (capacity <= 0) OR (elementCount >= capacity) THEN
            status := 16#8002;
        ELSE
            pSrc := pItem;
            pDst := pBuffer + (DINT_TO_UDINT(tail) * elementSize);
            FOR i := 0 TO elementSize - 1 DO
                (pDst + i)^ := (pSrc + i)^;
            END_FOR;
            tail := (tail + 1) MOD capacity;
            elementCount := elementCount + 1;
        END_IF;
    ELSIF deqEdge THEN
        IF (capacity <= 0) OR (elementCount <= 0) THEN
            status := 16#8001;
        ELSE
            pSrc := pBuffer + (DINT_TO_UDINT(head) * elementSize);
            pDst := pItem;
            FOR i := 0 TO elementSize - 1 DO
                (pDst + i)^ := (pSrc + i)^;
            END_FOR;
            head := (head + 1) MOD capacity;
            elementCount := elementCount - 1;
        END_IF;
    END_IF;
END_IF;

source.declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status : WORD;
END_VAR
VAR_IN_OUT
    item : VARIANT;
    buffer : VARIANT;
END_VAR
VAR
    enqueuePrev : BOOL;
    dequeuePrev : BOOL;
    head : DINT;
    tail : DINT;
    capacity : DINT;
    elemSize : UDINT;
    pSrc : POINTER TO BYTE;
    pDst : POINTER TO BYTE;
    udiCount : UDINT;
    udiOffset : UDINT;
    bEnqEdge : BOOL;
    bDeqEdge : BOOL;
END_VAR

source.implementation:
status := 16#0000;

IF reset THEN
    elementCount := 0;
    head := 0;
    tail := 0;
    enqueuePrev := enqueue;
    dequeuePrev := dequeue;
ELSE
    bEnqEdge := enqueue AND NOT enqueuePrev;
    bDeqEdge := dequeue AND NOT dequeuePrev;
    enqueuePrev := enqueue;
    dequeuePrev := dequeue;

    elemSize := item.udiSize;
    IF elemSize = 0 THEN
        elemSize := buffer.udiSize;
    END_IF
    IF elemSize > 0 THEN
        capacity := UDINT_TO_DINT(buffer.udiSize / elemSize);
    ELSE
        capacity := 0;
    END_IF
    IF capacity < 0 THEN
        capacity := 0;
    END_IF

    IF bEnqEdge THEN
        IF (capacity <= 0) OR (elementCount >= capacity) THEN
            status := 16#8002;
        ELSE
            IF elementCount <= 0 THEN
                head := 0;
                tail := 0;
            END_IF
            udiOffset := DINT_TO_UDINT(tail) * elemSize;
            pDst := buffer.pData + udiOffset;
            pSrc := item.pData;
            FOR udiCount := 1 TO elemSize DO
                pDst^ := pSrc^;
                pDst := pDst + 1;
                pSrc := pSrc + 1;
            END_FOR
            tail := tail + 1;
            IF tail >= capacity THEN
                tail := 0;
            END_IF
            elementCount := elementCount + 1;
        END_IF
    ELSIF bDeqEdge THEN
        IF (capacity <= 0) OR (elementCount <= 0) THEN
            status := 16#8001;
        ELSE
            udiOffset := DINT_TO_UDINT(head) * elemSize;
            pSrc := buffer.pData + udiOffset;
            pDst := item.pData;
            FOR udiCount := 1 TO elemSize DO
                pDst^ := pSrc^;
                pDst := pDst + 1;
                pSrc := pSrc + 1;
            END_FOR
            head := head + 1;
            IF head >= capacity THEN
                head := 0;
            END_IF
            elementCount := elementCount - 1;
            IF elementCount <= 0 THEN
                elementCount := 0;
            END_IF
        END_IF
    END_IF
END_IF

